i=t.index("{id:'when',"); j=t.index("{id:'logi',")
when=r'''{id:'when',name:'When are you going',verdict:'<b>Between a calendar and a trip bar: real weeks, no exact dates.</b> You were right that a month is not four weeks. These two show the true shape of each month (Monday to Sunday weeks, with a short week at the start or end when the month does not begin on a Monday) without asking for days. Option 3 is the earlier "best months" idea, unchanged. Press Keep on the one you like.',
 states:[{id:'a',label:'1 · Weeks strip',shots:['when']},{id:'b',label:'2 · Stacked weeks',shots:['when']},{id:'c',label:'3 · Best months',shots:['when']}],
 changes:[
  {id:'wo1',t:'Option 1: a strip of real weeks',w:'Two months side by side as one strip of week blocks, each as wide as the days it really has, so a short first or last week looks short. Tap the week you start, then choose how long, and the blocks fill across the month boundary. Use ‹ › to move along the year. We would keep the start week behind the scenes, so the month and the 7-day rule still work.'},
  {id:'wo2',t:'Option 2: the month as stacked weeks',w:'Pick a month and it shows as rows of weeks, seven small cells each, with the days that belong to the neighbouring month left faint. It is a calendar with the numbers taken out. Tap a row to start there, choose how long, and the rows fill down (and tell you when it runs into the next month).'},
  {id:'wo3',t:'Option 3: months that show how well they suit you',w:'The month grid, but each month carries a small bar for how well it suits your interests overall, and the best months are starred. Length is one row, and the week is dropped. (The bars here are illustrative.)'}],
 mock:function(on,s,st){
  var CY=2027;var len=ui(s,'len','2w');var LN=[['wk','Long weekend','3 to 4 days'],['1w','1 week',''],['2w','2 weeks',''],['3w','3+ weeks','']];
  var NB={wk:1,'1w':1,'2w':2,'3w':3}[len];var DAYS={wk:4,'1w':7,'2w':14,'3w':21}[len];
  function segs(y,m){var dim=new Date(y,m+1,0).getDate(),out=[],cur=null;for(var d=1;d<=dim;d++){var wd=new Date(y,m,d).getDay();if(!cur||wd===1){cur={d1:d,d2:d,m:m,y:y};out.push(cur);}else cur.d2=d;}return out;}
  function lenSeg(key){return '<div class="sg">'+LN.map(function(x){return '<button class="'+(len===x[0]?'sel':'')+'" '+D(s,'len',x[0])+'>'+(x[0]==='wk'?'Long<br>weekend':x[1])+'</button>';}).join('')+'</div>';}
  function endText(seg){var a=new Date(seg.y,seg.m,seg.d1);var e=new Date(a.getTime()+(DAYS-1)*864e5);var em=e.getMonth();return {txt:MONTHN[em].slice(0,3)+' '+e.getDate(),next:em!==seg.m};}
  if(st==='a'){var sm=ui(s,'sm',8),ss=ui(s,'ss',1);var m2=(sm+1)%12,y2=sm===11?CY+1:CY;var A=segs(CY,sm),B=segs(y2,m2);var all=A.concat(B);if(ss>=all.length)ss=0;
   function grp(arr,mm){var days=arr.reduce(function(n,x){return n+(x.d2-x.d1+1);},0);return '<div style="flex:'+days+' 1 0;min-width:0;font-size:11px;font-weight:800;color:var(--afg);border-left:1.5px solid var(--afg);padding-left:4px;margin-bottom:3px">'+MONTHN[mm]+'</div>';}
   var labels='<div style="display:flex;gap:2px">'+grp(A,sm)+grp(B,m2)+'</div>';
   var blocks='<div style="display:flex;gap:2px">'+all.map(function(x,i){var n=x.d2-x.d1+1;var inr=i>=ss&&i<ss+NB;return '<button '+D(s,'ss',i)+' style="flex:'+n+' 1 0;min-width:0;height:44px;border-radius:6px;background:'+(inr?'var(--ac)':'#e3ddd4')+';color:'+(inr?'#fff':'var(--afa)')+';font-size:10.5px;text-align:center;padding:0">'+x.d1+'</button>';}).join('')+'</div>';
   var seg=all[ss];var en=endText(seg);var sum='<div class="card" style="margin-top:12px;background:var(--as);border-color:var(--ac)"><b>Starts the week of '+MONTHN[seg.m].slice(0,3)+' '+seg.d1+'</b><div class="dim small" style="margin-top:3px">About '+(len==='wk'?'a long weekend':len==='1w'?'1 week':len==='2w'?'2 weeks':'3 weeks or more')+', to around '+en.txt+'.'+(en.next?' It runs into '+MONTHN[(seg.m+1)%12]+'.':'')+' Ranked for <b>'+MONTHN[seg.m]+'</b>.</div></div>';
   return {body:topbar(60)+'<div style="padding:0 16px"><h3>When are you going?</h3><p class="sub">Tap the week you start.</p><div class="card"><div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px"><button '+D(s,'sm',(sm+11)%12)+' style="font-size:20px;padding:2px 12px">‹</button><span class="dim small">Short weeks are short. Numbers are the first day.</span><button '+D(s,'sm',(sm+1)%12)+' style="font-size:20px;padding:2px 12px">›</button></div>'+labels+blocks+'</div><div class="lab">How long</div>'+lenSeg()+'<div style="margin-top:4px">'+sum+'</div></div>',foot:btn('Continue'),flush:true};}
  if(st==='b'){var mm=ui(s,'mm',8),sr=ui(s,'sr',1);var S=segs(CY,mm);if(sr>=S.length)sr=0;var next=MONTHN[(mm+1)%12];
   var head='<div style="display:grid;grid-template-columns:54px repeat(7,1fr);gap:3px;font-size:10.5px;color:var(--afa);text-align:center;margin-bottom:3px"><span></span>'+['M','T','W','T','F','S','S'].map(function(x){return '<span>'+x+'</span>';}).join('')+'</div>';
   var rows=S.map(function(x,i){var inr=i>=sr&&i<sr+NB;var first=new Date(CY,mm,x.d1).getDay();var offset=(first+6)%7;var cells='';for(var c=0;c<7;c++){var belongs=(c>=offset&&c<offset+(x.d2-x.d1+1));cells+='<span style="height:22px;border-radius:5px;background:'+(belongs?(inr?'var(--ac)':'#cfc6b6'):'#f0ece4')+'"></span>';}return '<button '+D(s,'sr',i)+' style="display:grid;grid-template-columns:54px repeat(7,1fr);gap:3px;align-items:center;width:100%;margin-bottom:4px"><span style="font-size:11px;color:'+(inr?'var(--ac)':'var(--adim)')+';font-weight:'+(inr?800:500)+'">'+MONTHN[mm].slice(0,3)+' '+x.d1+'</span>'+cells+'</button>';}).join('');
   var spill=(sr+NB>S.length);var seg=S[sr];var en=endText(seg);
   var sum='<div class="card" style="margin-top:8px;background:var(--as);border-color:var(--ac)"><b>Starts the week of '+MONTHN[mm].slice(0,3)+' '+seg.d1+'</b><div class="dim small" style="margin-top:3px">About '+(len==='wk'?'a long weekend':len==='1w'?'1 week':len==='2w'?'2 weeks':'3 weeks or more')+', to around '+en.txt+'.'+(spill||en.next?' It runs into '+next+'.':'')+'</div></div>';
   return {body:topbar(60)+'<div style="padding:0 16px"><h3>When are you going?</h3><p class="sub">Pick the month, then the week you start.</p><div style="display:flex;gap:7px;overflow-x:auto;padding-bottom:6px;scrollbar-width:none">'+MONTHS.map(function(x,i){return '<button class="pill'+(mm===i?' sel':'')+'" style="flex:none" '+D(s,'mm',i)+'>'+x+'</button>';}).join('')+'</div><div class="card" style="margin-top:6px">'+head+rows+'</div><div class="lab">How long</div>'+lenSeg()+sum+'</div>',foot:btn('Continue'),flush:true};}
  var m3=ui(s,'m3',null);var SCORE=[5.2,5.4,5.9,6.4,7.0,7.5,7.7,7.6,7.2,6.6,5.8,5.3];var best=SCORE.map(function(v,i){return [v,i];}).sort(function(x,y){return y[0]-x[0];}).slice(0,3).map(function(x){return x[1];});
  var tiles=MONTHS.map(function(x,i){var sel=m3===i;return '<button '+D(s,'m3',i)+' style="position:relative;border:1.5px solid '+(sel?'var(--ac)':'var(--aln)')+';background:'+(sel?'var(--as)':'#fff')+';border-radius:11px;padding:8px 0 7px;text-align:center"><div style="font-weight:'+(sel?800:600)+';font-size:13.5px">'+x+(best.indexOf(i)>=0?' <span style="color:var(--ac)">★</span>':'')+'</div><div style="height:5px;margin:6px 10px 0;border-radius:3px;background:#ece7df;overflow:hidden"><i style="display:block;height:100%;width:'+(SCORE[i]*10)+'%;background:'+colr(SCORE[i])+'"></i></div></button>';}).join('');
  return {body:topbar(60)+'<div style="padding:0 16px"><h3>When are you going?</h3><p class="sub">Months that suit your interests best are starred.</p><div class="card"><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:7px">'+tiles+'</div><p class="dim small" style="margin:10px 0 0">★ Best for you: '+best.slice().sort(function(a2,b2){return a2-b2;}).map(function(i){return MONTHN[i];}).join(', ')+'</p></div><div class="card"><h4>How long?</h4><p>Optional.</p>'+lenSeg()+'</div></div>',foot:btn('Continue',m3===null),flush:true};}},

'''
t=t[:i]+when+t[j:]

